   769
   770      switch( matvar->data_type ) {
   771          case MAT_T_DOUBLE:
   772          case MAT_T_SINGLE:
   773          case MAT_T_INT32:
   774          case MAT_T_INT16:
   775          case MAT_T_UINT16:
   776          case MAT_T_UINT8:
   777              break;
   778          default:
   779              return 1;
   780      }
   781
   782      if ( matvar->rank == 2 ) {
   783          if ( (size_t)stride[0]*(edge[0]-1)+start[0]+1 > matvar->dims[0] )
   784              err = 1;
   785          else if ( (size_t)stride[1]*(edge[1]-1)+start[1]+1 > matvar->dims[1] )
   786              err = 1;
