   796              ReadDataSlab2(mat,cdata->Re,matvar->class_type,matvar->data_type,
   797                  matvar->dims,start,stride,edge);
   798              (void)fseek((FILE*)mat->fp,matvar->internal->datapos+nbytes,SEEK_SET);
   799              ReadDataSlab2(mat,cdata->Im,matvar->class_type,
   800                  matvar->data_type,matvar->dims,start,stride,edge);
   801          } else {
   802              ReadDataSlab2(mat,data,matvar->class_type,matvar->data_type,
   803                  matvar->dims,start,stride,edge);
   804          }
   805      } else if ( matvar->isComplex ) {
   806          mat_complex_split_t *cdata = (mat_complex_split_t*)data;
   807          size_t nbytes = Mat_SizeOf(matvar->data_type);
   808          err = SafeMulDims(matvar, &nbytes);
   809          if ( err ) {
   810              Mat_Critical("Integer multiplication overflow");
   811              return err;
   812          }
   813
   814          ReadDataSlabN(mat,cdata->Re,matvar->class_type,matvar->data_type,
