  1821  /** @brief Calculates the size of a matlab variable in bytes
  1822   *
  1823   * @ingroup MAT
  1824   * @param matvar matlab variable
  1825   * @returns size of the variable in bytes, or 0 on error
  1826   */
  1827  size_t
  1828  Mat_VarGetSize(matvar_t *matvar)
  1829  {
  1830      int err;
  1831      size_t i;
  1832      size_t bytes = 0, overhead = 0, ptr = 0;
  1833
  1834  #if defined(_WIN64) || (defined(__SIZEOF_POINTER__) && (__SIZEOF_POINTER__ == 8)) || (defined(SIZEOF_VOID_P) && (SIZEOF_VOID_P == 8))
  1835      /* 112 bytes cell/struct overhead for 64-bit system */
  1836      overhead = 112;
  1837      ptr = 8;
  1838  #elif defined(_WIN32) || (defined(__SIZEOF_POINTER__) && (__SIZEOF_POINTER__ == 4)) || (defined(SIZEOF_VOID_P) && (SIZEOF_VOID_P == 4))
  1839      /* 60 bytes cell/struct overhead for 32-bit system */
  1840      overhead = 60;
  1841      ptr = 4;
  1842  #endif
  1843
  1844      if ( matvar->class_type == MAT_C_STRUCT ) {
  1845          matvar_t **fields = (matvar_t**)matvar->data;
  1846          size_t field_name_length;
  1847          if ( NULL != fields ) {
  1848              size_t nelems_x_nfields = matvar->internal->num_fields;
  1849              err = SafeMulDims(matvar, &nelems_x_nfields);
  1850              err |= SafeMul(&bytes, nelems_x_nfields, overhead);
