  1857                          err = SafeAdd(&bytes, bytes, Mat_VarGetSize(fields[i]));
  1858                          if ( err )
  1859                              return 0;
  1860                      } else {
  1861                          bytes -= overhead;
  1862                          bytes += ptr;
  1863                      }
  1864                  }
  1865              }
  1866          }
  1867          err = SafeMul(&field_name_length, 64 /* max field name length */, matvar->internal->num_fields);
